// src/utils/api.js
const API_BASE = process.env.REACT_APP_API_BASE || ""; // để trống dùng proxy /api
export async function apiJson(path, opts = {}) {
  const url = API_BASE + path;
  const { headers, body, ...rest } = opts;

  const res = await fetch(url, {
    ...rest,
    // luôn gửi cookie/session kèm request
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      ...(headers || {}),
    },
    // tự stringify nếu body là object
    body:
      body == null
        ? undefined
        : typeof body === "string"
        ? body
        : JSON.stringify(body),
    cache: "no-store", // tránh dính cache khi auth/cors
  });

  // 204 No Content thì không cần parse json
  if (res.status === 204) return null;

  let data = null;
  try {
    data = await res.json();
  } catch {
    data = null;
  }

  if (!res.ok) {
    throw new Error((data && (data.error || data.message)) || `HTTP ${res.status}`);
  }
  return data;
}


/** tiện ích: chuẩn hoá danh sách devices cho mọi định dạng BE */
export function normalizeDevices(resp) {
  if (Array.isArray(resp)) return resp;
  if (Array.isArray(resp?.devices)) return resp.devices;
  return [];
}
