// src/components/GlobalAlarm/index.jsx
import { useEffect, useState, useCallback, useRef } from "react";
import { useSelector } from "react-redux";
import { useTranslation } from "react-i18next";

/* ====== Cấu hình API cố định ====== */
const API_BASE = "http://localhost:5000";

/* Gắn base URL an toàn cho cả "/api/..." lẫn "api/..." */
const withBase = (path) => {
  try {
    return new URL(path, API_BASE).toString();
  } catch {
    // Fallback đơn giản
    const p = String(path || "");
    if (p.startsWith("http://") || p.startsWith("https://")) return p;
    return `${API_BASE.replace(/\/+$/, "")}/${p.replace(/^\/+/, "")}`;
  }
};

/* Helper GET JSON (log khi backend trả không phải JSON) */
async function getJson(path, opts = {}) {
  const url = withBase(path);
  const res = await fetch(url, {
    method: "GET",
    credentials: "include", // giữ cookie/session khi cần
    headers: { "Accept": "application/json", ...(opts.headers || {}) },
    ...opts,
  });
  const text = await res.text();
  try {
    return JSON.parse(text);
  } catch {
    console.warn("getJson: Not JSON", { url, status: res.status, body: text?.slice(0, 200) });
    throw new Error(`API not JSON: ${url}`);
  }
}

/* ====== Poll interval từ settings (fallback 10s) ====== */
const usePollSec = () =>
  useSelector((s) => s?.settings?.pollIntervalSec ?? 10);

/* ====== Khí: 0=Normal; 1/2=Fault (riêng VA: chỉ 2=Fault) ====== */
const GAS_ORDER = ["O2", "N2O", "MA4", "MA7", "VA", "CO2"];

const isGasFault = (code, status012) => {
  const s = Number(status012);
  const gas = String(code || "").toUpperCase();
  if (gas === "VA") return s === 2;          // VA: chỉ 2 là lỗi
  return s === 1 || s === 2;                 // các khí khác: 1 hoặc 2 đều lỗi
};

const shapeGas = (raw) => {
  const by = {};
  (raw || []).forEach((it) => {
    const code = String(it?.code ?? it?.keyword ?? "").toUpperCase();
    if (!GAS_ORDER.includes(code)) return;
    const status = Number(it?.status ?? 0);
    by[code] = { code, status, fault: isGasFault(code, status) };
  });
  return GAS_ORDER.map((c) => by[c] ?? { code: c, status: 0, fault: false });
};

/* ====== Chuẩn hoá Power (true=Fault, false=Normal) ====== */
// const POWER_KEYS = ["ups", "ips", "main"];
const POWER_KEYS = ["ips"];

const shapePower = (raw) => {
  const arr = Array.isArray(raw) ? raw : [];
  const byKey = Object.fromEntries(
    arr.map((it) => [String(it?.key || "").toLowerCase(), !!it?.status])
  );
  return POWER_KEYS.map((k) => ({ key: k, fault: !!byKey[k] }));
};

/* ====== WebAudio beep (offline) ====== */
let audioCtx;
function ensureAudioCtx() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (audioCtx.state === "suspended") audioCtx.resume();
  return audioCtx;
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function tone(freq = 900, durMs = 140, type = "square", gain = 0.08) {
  const ctx = ensureAudioCtx();
  const osc = ctx.createOscillator();
  const g = ctx.createGain();
  osc.type = type;
  osc.frequency.value = freq;
  g.gain.value = gain;
  osc.connect(g).connect(ctx.destination);
  osc.start();
  await sleep(durMs);
  osc.stop();
  osc.disconnect();
  g.disconnect();
}
async function alarmBeepPattern() {
  await tone(920, 140, "square", 0.09);
  await sleep(120);
  await tone(920, 140, "square", 0.09);
}

/* ====== Component toàn cục ====== */
export default function GlobalAlarm() {
  const { t } = useTranslation();
  const pollIntervalSec = usePollSec();

  const [faultGas, setFaultGas] = useState(false);
  const [faultPower, setFaultPower] = useState(false);
  const hasFault = faultGas || faultPower;

  const [muted, setMuted] = useState(() => localStorage.getItem("alarmMuted") === "1");

  // Theo dõi “sự cố hiện tại” bằng chữ ký (signature)
  const [faultSig, setFaultSig] = useState(""); // ví dụ: "G:O2,CO2|P:ups"
  const prevFaultSigRef = useRef("");
  const [mutedIncidentSig, setMutedIncidentSig] = useState(
    () => localStorage.getItem("alarmMutedIncidentSig") || ""
  );

  // Unlock audio sau 1 lần chạm
  useEffect(() => {
    const unlock = () => { try { ensureAudioCtx(); } catch {} };
    window.addEventListener("pointerdown", unlock, { once: true });
    return () => window.removeEventListener("pointerdown", unlock);
  }, []);

  // Poll GAS + POWER từ API_BASE
  const loadAll = useCallback(async () => {
    try {
      const [gasRes, powerRes] = await Promise.allSettled([
        getJson("/api/gas"),
        getJson("/api/power"),
      ]);

      let gasFaults = [];
      if (gasRes.status === "fulfilled") {
        const payload = gasRes.value;
        const shaped = shapeGas(Array.isArray(payload?.data) ? payload.data : payload);
        gasFaults = shaped.filter((g) => g.fault).map((g) => g.code);
        setFaultGas(gasFaults.length > 0);
      } else {
        console.warn("GAS fetch failed:", gasRes.reason);
      }

      let powerFaults = [];
      if (powerRes.status === "fulfilled") {
        const payload = powerRes.value;
        const shapedP = shapePower(Array.isArray(payload?.data) ? payload.data : payload);
        powerFaults = shapedP.filter((p) => p.fault).map((p) => p.key);
        setFaultPower(powerFaults.length > 0);
      } else {
        console.warn("POWER fetch failed:", powerRes.reason);
      }

      // cập nhật chữ ký sự cố
      const sigG = gasFaults.length ? `G:${gasFaults.sort().join(",")}` : "";
      const sigP = powerFaults.length ? `P:${powerFaults.sort().join(",")}` : "";
      const sig = [sigG, sigP].filter(Boolean).join("|");
      setFaultSig(sig);
    } catch (e) {
      console.warn("loadAll error:", e);
    }
  }, []);

  useEffect(() => {
    loadAll();
    const id = setInterval(loadAll, Math.max(1, Number(pollIntervalSec)) * 1000);
    return () => clearInterval(id);
  }, [loadAll, pollIntervalSec]);

  // Phát tiếng định kỳ khi có lỗi & chưa mute
  useEffect(() => {
    let id;
    if (hasFault && !muted) {
      alarmBeepPattern();
      id = setInterval(alarmBeepPattern, 6000);
    }
    return () => id && clearInterval(id);
  }, [hasFault, muted]);

  // Beep một lần khi có SỰ CỐ MỚI, kể cả đang muted
  useEffect(() => {
    const prev = prevFaultSigRef.current;
    if (faultSig !== prev) {
      prevFaultSigRef.current = faultSig;

      if (!faultSig) {
        if (mutedIncidentSig !== "") {
          setMutedIncidentSig("");
          localStorage.removeItem("alarmMutedIncidentSig");
        }
        return;
      }

      if (muted && faultSig !== mutedIncidentSig) {
        alarmBeepPattern();
        setMutedIncidentSig(faultSig);
        localStorage.setItem("alarmMutedIncidentSig", faultSig);
      }
    }
  }, [faultSig, muted, mutedIncidentSig]);

  // Label nút theo nguồn lỗi
  let label = t("alarm.noFault", "No Fault");
  if (faultGas && faultPower) label = t("alarm.gasPowerFault", "Gas + Power Fault");
  else if (faultGas) label = t("alarm.gasFault", "Gas Fault");
  else if (faultPower) label = t("alarm.powerFault", "Power Fault");

  // Toggle mute + lưu localStorage
  const toggleMute = () => {
    const next = !muted;
    setMuted(next);
    localStorage.setItem("alarmMuted", next ? "1" : "0");

    const sig = faultSig || "";
    setMutedIncidentSig(sig);
    if (sig) localStorage.setItem("alarmMutedIncidentSig", sig);
    else localStorage.removeItem("alarmMutedIncidentSig");
  };

  return (
    <div className="fixed bottom-3 right-3 z-50">
      <button
        type="button"
        onClick={toggleMute}
        className={[
          "px-3 py-2 rounded-xl border text-sm font-semibold shadow-sm transition",
          muted
            ? "bg-slate-200 text-slate-700 border-slate-300 hover:bg-slate-100"
            : hasFault
            ? "bg-rose-600 text-white border-rose-600 hover:bg-rose-700 animate-pulse"
            : "bg-emerald-600 text-white border-emerald-600 hover:bg-emerald-700",
        ].join(" ")}
        aria-pressed={!muted}
        aria-live="polite"
        title={muted ? t("alarm.unmute", "Unmute alarm") : t("alarm.mute", "Mute alarm")}
      >
        {muted ? t("alarm.muted", "Alarm Muted") : label}
      </button>
    </div>
  );
}
